        value_case((string_address) "%f%n", (string_address) "inf",
                   1, 0xA5A5A5A57F800000ULL, 3);
        value_case((string_address) "%f%n", (string_address) "-inf",
                   1, 0xA5A5A5A5FF800000ULL, 4);
        value_case((string_address) "%f%n", (string_address) "INF",
                   1, 0xA5A5A5A57F800000ULL, 3);
